(* [comment removed for export] *)
Definition bd_rs (bil : Z) (b : bilv) (vsc : pixv) (ps : list pixe) (lps : list Z) : list Z :=
  [p_data vsc] ++ [b_pixsc b] ++ flat_map (fun e => [p_data (pe_v e); pe_pix e]) ps ++ [b_parr b; b_barr b; b_ba b; b_pixac b]
  ++ [b_spatial b; b_range b; b_nc b; b_kindex b; b_kfract b] ++ lps ++ [b_lineset b; bil].

